// Iterator consumer example:
const dual = getDualStream(producer);
for await (const chunk of dual.asAsyncIterator()) { process(chunk) }

// Drain-and-swap to WebStream:
const dual = getDualStream(producer);
const it = dual.asAsyncIterator();
await dual.swapTo({type:'web'}, {timeoutMs: 2000});
const rs = dual.asWebStream();
rs.pipeTo(dest);

// Shared fanout mode:
const dual = getDualStream(producer);
const iter = dual.asAsyncIterator({mode:'shared'});
const rs = dual.asWebStream({mode:'shared'});
// both consumers receive the same chunks
